function safe(action){return (...args)=>{try{return action(...args);}catch(error){notify(error.message,true);}};}
function setView(view){if(!['training','builder','data'].includes(view))return;closeMenu();if(view!=='builder'){closeExplain();closeDrawer();}activeView=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='view-'+view));document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('selected',button.dataset.view===view));if(view==='builder'){renderPalette();renderGraph();requestAnimationFrame(fitGraph);}if(view==='data')renderDataset();requestAnimationFrame(drawAll);syncHeader();}
// #embedded: the catalog frames the page and draws its header. The page reports the tab it is on and the model badge; the catalog sends back the tab and the action picked there.
const embedded=location.hash==='#embedded';let lastHeader='';
