function readSettings(){const lr=+$('learningRate').value,maxSteps=+$('maxSteps').value,patience=+$('patience').value,goal=+$('goal').value;if(!Number.isFinite(lr)||lr<.0001||lr>.3)throw Error('Скорость обучения: от 0,0001 до 0,3.');if(!Number.isInteger(maxSteps)||maxSteps<1||maxSteps>10000)throw Error('Предел: от 1 до 10 000 шагов.');if(!Number.isInteger(patience)||patience<0||patience>200)throw Error('Терпение: от 0 до 200 проверок.');const metric=$('monitorMetric').value;if(!Number.isFinite(goal)||goal<0||goal>(metric==='accuracy'?100:20))throw Error(metric==='accuracy'?'Целевая точность: 0–100%.':'Целевая ошибка: 0–20.');return {lr,objective:$('objective').value,optimizer:$('optimizer').value,maxSteps,patience,goal:metric==='accuracy'?goal/100:goal,metric,validationEvery:5,restoreBest:$('restoreBest').checked,clip:3};}
function pause(){if(run&&run.state==='running'){run.state='paused';run.reason='Обучение приостановлено';}if(worker)worker.postMessage({type:'pause',generation});else if(run){clearTimeout(inlineTimer);run.pause();renderAll();}}
