function singleStep(){if(settingsDirty)applySettings();if(run.state==='stopped'){notify('Эксперимент завершён. Сбросьте веса или измените пределы.');return;}if(worker)worker.postMessage({type:'step',generation});else{run.advance();if(run.state!=='stopped')run.pause();renderAll();}}
function resetModel(){pause();model=new Model(data,model.plan,model.D,model.initialSeed);initializeSession();notify('Веса сброшены с тем же зерном.');}
