 $('flowButton').onclick=safe(()=>openDrawer(drawerFocus));
 $('explainNode').onclick=safe(()=>{const n=graph.nodes.find(n=>n.id===selectedNode);if(n)showExplain(n);});
 $('matrixNode').onclick=safe(()=>{const n=graph.nodes.find(n=>n.id===selectedNode);if(n&&!['input','output'].includes(n.type))openDrawer(n.id);else if(n)notify('У блока «'+n.name+'» нет внутренних матриц: '+nodeShape(n));});
 $('flowPipeline').addEventListener('click',safe(event=>{const chip=event.target.closest('[data-chip]');if(!chip)return;drawerFocus=chip.dataset.chip;renderDrawer();}));
